import React, { useState, useEffect } from 'react';
import api from '../api';

function BranchPage() {

    const [branches, setBranches] = useState([]);
    const [loading, setLoading] = useState(true);
    const [error, setError] = useState('');
    const [showForm, setShowForm] = useState(false);
    const [editingItem, setEditingItem] = useState(null);

    const [name, setName] = useState('');
    const [location, setLocation] = useState('');
    const [address, setAddress] = useState('');
    const [phone, setPhone] = useState('');

    function fetchBranches() {

        setLoading(true);

        api.findAllBranches().then(function(response) {

            setBranches(response.data);
            setError('');
            setLoading(false);

        }).catch(function() {

            setError('Failed to fetch branches.');
            setLoading(false);

        });

    }

    useEffect(function() {
        fetchBranches();
    }, []);

    function resetForm() {

        setName('');
        setLocation('');
        setAddress('');
        setPhone('');
        setEditingItem(null);

    }

    function openEditForm(branch) {

        setName(branch.name);
        setLocation(branch.location);
        setAddress(branch.address || '');
        setPhone(branch.phone || '');
        setEditingItem(branch);
        setShowForm(true);

    }

    function handleSubmit(e) {

        e.preventDefault();

        const data = {
            name: name,
            location: location,
            address: address,
            phone: phone
        };

        if (editingItem) {

            api.updateBranch(editingItem.id, data).then(function() {

                resetForm();
                setShowForm(false);
                fetchBranches();

            }).catch(function(err) {
                var message = err.response?.data?.message || 'Failed to update branch.';
                setError(message);
            });

        } else {

            api.saveBranch(data).then(function() {

                resetForm();
                setShowForm(false);
                fetchBranches();

            }).catch(function(err) {
                var message = err.response?.data?.message || 'Failed to save branch.';
                setError(message);
            });

        }

    }

    function handleDelete(id) {

        var confirmed = window.confirm('Delete this branch?');

        if (!confirmed) {
            return;
        }

        api.deleteBranch(id).then(function() {
            fetchBranches();
        }).catch(function(err) {
            var message = err.response?.data?.message || 'Failed to delete branch.';
            setError(message);
        });

    }

    if (loading) {

        return (
            <div style={{ textAlign: 'center', padding: '2rem' }}>
                <p>Loading branches...</p>
            </div>
        );

    }

    return (

        <div>

            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '1rem' }}>

                <h2 style={{ margin: 0, color: '#1a1a2e' }}>Branches</h2>

                <button onClick={function() { resetForm(); setShowForm(true); }}
                    style={{ background: '#fbbf24', color: '#1a1a2e', border: 'none', padding: '0.5rem 1rem', borderRadius: '8px', cursor: 'pointer', fontWeight: 600 }}>
                    Add Branch
                </button>

            </div>

            {error && (

                <div style={{ background: '#fef2f2', color: '#dc2626', padding: '0.75rem 1rem', borderRadius: '8px', marginBottom: '1rem', display: 'flex', justifyContent: 'space-between' }}>

                    <span>Error: {error}</span>

                    <button onClick={function() { setError(''); }}
                        style={{ background: 'none', border: 'none', color: '#dc2626', cursor: 'pointer', fontWeight: 'bold' }}>
                        X
                    </button>

                </div>

            )}

            {showForm && (

                <div style={{ background: '#fff', borderRadius: '12px', padding: '1.5rem', marginBottom: '1.5rem', border: '1px solid #e5e7eb' }}>

                    <h3 style={{ margin: '0 0 1rem', color: '#1a1a2e' }}>
                        {editingItem ? 'Edit Branch' : 'Add New Branch'}
                    </h3>

                    <form onSubmit={handleSubmit}>

                        <div style={{ marginBottom: '0.8rem' }}>

                            <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                Branch Name
                            </label>

                            <input type="text" value={name}
                                onChange={function(e) { setName(e.target.value); }}
                                required
                                placeholder="e.g. Main Branch"
                                style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', boxSizing: 'border-box' }} />

                        </div>

                        <div style={{ marginBottom: '0.8rem' }}>

                            <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                Location
                            </label>

                            <input type="text" value={location}
                                onChange={function(e) { setLocation(e.target.value); }}
                                required
                                placeholder="e.g. Dar es Salaam"
                                style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', boxSizing: 'border-box' }} />

                        </div>

                        <div style={{ marginBottom: '0.8rem' }}>

                            <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                Address
                            </label>

                            <input type="text" value={address}
                                onChange={function(e) { setAddress(e.target.value); }}
                                placeholder="e.g. 123 India Street"
                                style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', boxSizing: 'border-box' }} />

                        </div>

                        <div style={{ marginBottom: '1rem' }}>

                            <label style={{ display: 'block', marginBottom: '0.25rem', fontWeight: 500, color: '#374151' }}>
                                Phone
                            </label>

                            <input type="text" value={phone}
                                onChange={function(e) { setPhone(e.target.value); }}
                                placeholder="e.g. +255-712-000-111"
                                style={{ width: '100%', padding: '0.6rem', border: '1px solid #d1d5db', borderRadius: '8px', fontSize: '0.9rem', boxSizing: 'border-box' }} />

                        </div>

                        <div style={{ display: 'flex', gap: '0.75rem' }}>

                            <button type="submit"
                                style={{ flex: 1, padding: '0.6rem', background: '#059669', color: '#fff', border: 'none', borderRadius: '8px', fontWeight: 600, cursor: 'pointer' }}>
                                {editingItem ? 'Update' : 'Save'}
                            </button>

                            <button type="button" onClick={function() { setShowForm(false); resetForm(); }}
                                style={{ padding: '0.6rem 1.2rem', background: '#f3f4f6', color: '#374151', border: '1px solid #d1d5db', borderRadius: '8px', cursor: 'pointer' }}>
                                Cancel
                            </button>

                        </div>

                    </form>

                </div>

            )}

            {!showForm && branches.length === 0 && (

                <div style={{ textAlign: 'center', padding: '2rem', background: '#fff', borderRadius: '10px', border: '1px solid #e5e7eb' }}>

                    <p style={{ color: '#6b7280' }}>No branches added yet.</p>

                </div>

            )}

            {!showForm && branches.map(function(branch) {

                return (

                    <div key={branch.id}
                        style={{ background: '#fff', borderRadius: '10px', padding: '1rem', marginBottom: '0.75rem', border: '1px solid #e5e7eb', display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>

                        <div>

                            <div style={{ fontWeight: 600, color: '#111827' }}>{branch.name}</div>

                            <div style={{ fontSize: '0.85rem', color: '#6b7280' }}>
                                {branch.location} {branch.address ? '- ' + branch.address : ''}
                            </div>

                            {branch.phone && (
                                <div style={{ fontSize: '0.85rem', color: '#6b7280' }}>{branch.phone}</div>
                            )}

                        </div>

                        <div style={{ display: 'flex', gap: '0.4rem' }}>

                            <button onClick={function() { openEditForm(branch); }}
                                style={{ background: '#fffbeb', color: '#92400e', border: '1px solid #fde68a', padding: '0.35rem 0.7rem', borderRadius: '6px', cursor: 'pointer', fontSize: '0.8rem' }}>
                                Edit
                            </button>

                            <button onClick={function() { handleDelete(branch.id); }}
                                style={{ background: '#fef2f2', color: '#dc2626', border: '1px solid #fecaca', padding: '0.35rem 0.7rem', borderRadius: '6px', cursor: 'pointer', fontSize: '0.8rem' }}>
                                Delete
                            </button>

                        </div>

                    </div>

                );

            })}

        </div>

    );

}

export default BranchPage;
